  setMedioRecorderOff() {
    this.setState({ micOn: true });
    if (this.state?.selectedAudioDevice) {
      this.setState({
        isRecording: true
      });
      const audio = this.state?.selectedAudioDevice?.length > 0 ? { deviceId: null } : true;
      navigator.mediaDevices.getUserMedia({ audio: true, video: false }).then((stream) => {
        const options = { mimeType: "audio/webm" };
        this.mediaRecorder = new MediaRecorder(stream, options);
        this.mediaRecorder.addEventListener("dataavailable", (e) => {
          this.state.recordedChunksData.push(e.data);
        });
        this.mediaRecorder.addEventListener("stop", () => {
          const val1 = window.location.search;
          const daata1 = val1.split("=")
          const user_id = daata1[3]
          const blob = new Blob(this.state.recordedChunksData, { type: "webm" })
          const a = document.createElement("a");
          a.href = URL.createObjectURL(new Blob(this.state.recordedChunksData));
          a.download = `Audio${0 + 1}.webm`;
          document.body.appendChild(a);
          a.click();
          document.body.removeChild(a);
          a.remove();

          var formData = new FormData();
          formData.append('file', this.state.recordedChunksData[0]);
          formData.append('user_id', `${user_id}`);
          axios({
            method: "post",
            url: "https://159.223.251.167:3000/uploadSong",
            // url: "http://localhost:3000/uploadSong",
            data: formData
          })
            .then((res) => {
              if (res?.data?.success == false) {
                MESSAGE.error(res?.data?.message, 4)
              } else {
                MESSAGE.success("Song uploaded successfully.", 4)
              }
            })
            .catch((err) => {
              console.log(err)
            })
          // end of the upload song
          stream.getTracks().forEach((track) => {
            track.stop()
          })
        });
        this.mediaRecorder.start();
      });
    }
  }

