  handlePermissionState() {
    navigator.permissions.query({ name: "microphone" }).then((queryResults) => {
      console.log(queryResults?.state, "queryResults")
      this.setState({
        microphonePermissionState: queryResults?.state
      })
      this.getAvailableAudioDevices().then((devices) => {
        // console.log(devices, "devices")
        this.setState({
          availableDevices: devices,
          selectedAudioDevice: devices.find((device) => device.id === "default")?.id
        })
      })
      queryResults.onChange = function (onChangeResult) {
        if (onChangeResult.target) {
          this.microphonePermissionState = ((onChangeResult?.target)?.state)
        }
      }
    })
  }

  getAvailableAudioDevices() {
    return new Promise((resolve) => {
      navigator.mediaDevices.enumerateDevices().then((devices) => {
        const availableDevices = devices?.filter((d) => d?.kind === "audiooutput")
          .map((d) => {
            return { id: d.deviceId, name: d.label };
          });
        resolve(availableDevices)
      });
    })
  }

  getSongById() {
    const val = window.location.search;
    const daata = val.split("=")
    const song_id = daata[1].slice(0, daata[1].length - 6)
    // console.log(daata[2]?.slice(0, daata[2].length - 5), "=====>>>", daata[3])
    const music_volume = daata[2]?.slice(0, daata[2].length - 5)
    if (music_volume == 1) {
      this.setState({
        drumVolume: 0,
        bassVolume: 0,
        guitarVolume: 100,
        keyboardVolume: 0,
        isDrumDisable: true,
        isBassDisable: true,
        isGuitarDisable: false,
        isKeyBoardDisable: true,
      })
    }
    else if (music_volume == 2) {
      this.setState({
        drumVolume: 0,
        bassVolume: 100,
        guitarVolume: 0,
        keyboardVolume: 0,
        isDrumDisable: true,
        isBassDisable: false,
        isGuitarDisable: true,
        isKeyBoardDisable: true,
      })
    }
    else if (music_volume == 3) {
      this.setState({
        drumVolume: 100,
        bassVolume: 0,
        guitarVolume: 0,
        keyboardVolume: 0,
        isDrumDisable: false,
        isBassDisable: true,
        isGuitarDisable: true,
        isKeyBoardDisable: true,
      })
    }
    else if (music_volume == 4) {
      this.setState({
        drumVolume: 0,
        bassVolume: 0,
        guitarVolume: 0,
        keyboardVolume: 100,
        isDrumDisable: true,
        isBassDisable: true,
        isGuitarDisable: true,
        isKeyBoardDisable: false,
      })
    } else {
      this.setState({
        drumVolume: 100,
        bassVolume: 100,
        guitarVolume: 100,
        keyboardVolume: 100,
        isDrumDisable: true,
        isBassDisable: true,
        isGuitarDisable: true,
        isKeyBoardDisable: false,
      })
    }
    this.setState({
      music_volume_handle: music_volume
    })
    const data = {
      // id: 239
      id: song_id
    }
    axios({
      method: "post",
      // url: "http://localhost:3000/fetchSongsById",
      url: "https://159.223.251.167:3000/fetchSongsById",
      headers: { "content-type": "application/x-www-form-urlencoded" },
      data: data,
    })
      .then(async (res) => {
        if (res?.data?.success == true) {
          this.setState({
            isPlaying: true,
            playButtonNextAction: 'Play'
          });
          const context = new (window.AudioContext || window.webkitAudioContext)();
          const data_demo = []
          this.setState({
            chords_url: res?.data?.data[0]?.chords_songs
          })
          // const context = new AudioContext();
          const data_buffers =
            await Promise.all(
              res?.data?.data[0]?.songs?.map((url) =>
                fetch(url, { mode: 'cors' })
                  .then((res) => {
                    if (!res.ok) {
                      throw new Error(`HTTPs error, status = ${res.status}`);
                    }
                    return res?.arrayBuffer()
                  })
              ))
          const audio_buffers = await Promise.all(
            data_buffers.map(async (buf) => {
              return context.decodeAudioData(buf)
            })
          )

          this.setState({
            audioBuff: audio_buffers
          });
          for (var i = 0; i < audio_buffers?.length; i++) {
            this.inputAudio.push({
              name: "Test",
              data: audio_buffers[i],
              source: null,
              gainNode: null,
              gain: 100,
            });
            this.setState({
              playButtonNextAction: 'Play',
              timeA: 0,
              playingAt: 0,
              timeB: this?.inputAudio[i]?.data?.duration,
            });
          }
        }
      })
      .catch((err) => {
        console.log(err);
      })
  }

